package com.familygrowth.infrastructure;
import com.familygrowth.application.FamilyGrowthService;import com.familygrowth.application.Stage3Service;import com.familygrowth.application.Stage7Store;import com.familygrowth.domain.Stage7Models;import com.familygrowth.domain.Stage7Models.*;
import java.math.BigDecimal;import java.math.RoundingMode;import java.sql.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository class JdbcStage7Store implements Stage7Store{
 private final JdbcTemplate jdbc;JdbcStage7Store(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Override public VirtualFund createFund(UUID family,String name,String risk,UUID actor,Instant now){if(name.isBlank()||name.length()>120||risk.isBlank()||risk.length()>80)throw new IllegalArgumentException("Fund is invalid");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO virtual_fund(id,family_id,name,risk_label,active,version,notice,actor_id,created_at) VALUES(?,?,?,?,TRUE,0,?,?,?)",id,family,name,risk,Stage7Models.NOTICE,actor,ts(now));return fund(family,id);}
 @Override public List<VirtualFund> funds(UUID family){return jdbc.query("SELECT * FROM virtual_fund WHERE family_id=? AND active=TRUE ORDER BY created_at,id",this::fundRow,family);}
 @Override public FundNav addNav(UUID family,UUID fundId,LocalDate date,BigDecimal nav,UUID actor,Instant now){lockFund(family,fundId);var previous=latestNav(family,fundId);BigDecimal change=previous.map(p->nav.subtract(p.nav()).multiply(new BigDecimal("100")).divide(p.nav(),4,RoundingMode.HALF_UP)).orElse(new BigDecimal("0.0000"));if(change.compareTo(new BigDecimal("-50"))<0||change.compareTo(new BigDecimal("50"))>0)throw new Stage3Service.ConflictException("NAV change exceeds the simulation guardrail");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO fund_nav(id,family_id,fund_id,nav_date,nav,change_percent,actor_id,created_at) VALUES(?,?,?,?,?,?,?,?)",id,family,fundId,date,nav,change,actor,ts(now));return navById(id);}
 @Override public FundFeeRule createFeeRule(UUID family,UUID fundId,BigDecimal buy,BigDecimal sell,UUID actor,Instant now){lockFund(family,fundId);Long version=jdbc.queryForObject("SELECT COALESCE(MAX(rule_version),0)+1 FROM fund_fee_rule WHERE fund_id=?",Long.class,fundId);jdbc.update("UPDATE fund_fee_rule SET active=FALSE WHERE fund_id=? AND active=TRUE",fundId);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO fund_fee_rule(id,family_id,fund_id,rule_version,buy_fee_rate,sell_fee_rate,active,actor_id,created_at) VALUES(?,?,?,?,?,?,TRUE,?,?)",id,family,fundId,version,buy,sell,actor,ts(now));return activeRule(family,fundId);}
 @Override public boolean childMayTrade(UUID family,UUID child){Integer count=jdbc.queryForObject("SELECT COUNT(*) FROM child_profile WHERE family_id=? AND id=? AND age_stage NOT IN('INFANT_0_2','EARLY_CHILDHOOD_2_5')",Integer.class,family,child);return count!=null&&count==1;}
 @Override public TradePreview createPreview(UUID family,UUID child,UUID fundId,TradeSide side,BigDecimal input,Instant expires,Instant now){VirtualFund fund=fund(family,fundId);if(!fund.active())throw new Stage3Service.ConflictException("Fund is inactive");FundNav nav=latestNav(family,fundId).orElseThrow(()->new Stage3Service.ConflictException("Fund has no NAV"));FundFeeRule rule=activeRule(family,fundId);BigDecimal rate=side==TradeSide.BUY?rule.buyFeeRate():rule.sellFeeRate();TradeQuote q=Stage7Models.quote(side,input,nav.nav(),rate);UUID id=UUID.randomUUID();jdbc.update("""
 INSERT INTO fund_trade_preview(id,family_id,child_id,fund_id,side,input_amount,gross_money,fee_amount,net_money,shares,nav_id,nav,fee_rule_id,fee_rule_version,status,expires_at,notice,created_at)
 VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,'OPEN',?,?,?)
 """,id,family,child,fundId,side.name(),q.inputAmount(),q.grossMoney(),q.feeAmount(),q.netMoney(),q.shares(),nav.id(),nav.nav(),rule.id(),rule.version(),ts(expires),Stage7Models.NOTICE,ts(now));return preview(family,id).orElseThrow();}
 @Override public Optional<TradePreview> preview(UUID family,UUID id){return jdbc.query("SELECT * FROM fund_trade_preview WHERE family_id=? AND id=?",this::previewRow,family,id).stream().findFirst();}
 @Override public Optional<FundTradeOrder> orderByKey(UUID family,String key){return jdbc.query("SELECT * FROM fund_trade_order WHERE family_id=? AND idempotency_key=?",this::orderRow,family,key).stream().findFirst();}
 @Override public FundTradeOrder confirm(UUID family,UUID previewId,String key,UUID actor,Instant now){TradePreview p=jdbc.query("SELECT * FROM fund_trade_preview WHERE family_id=? AND id=? FOR UPDATE",this::previewRow,family,previewId).stream().findFirst().orElseThrow(FamilyGrowthService.NotFoundException::new);if(p.status()==PreviewStatus.CONFIRMED){FundTradeOrder existing=jdbc.query("SELECT * FROM fund_trade_order WHERE id=?",this::orderRow,p.orderId()).stream().findFirst().orElseThrow();if(!key.equals(existing.idempotencyKey()))throw new Stage3Service.ConflictException("Fund preview is already confirmed");return existing;}FundNav latest=latestNav(family,p.fundId()).orElseThrow();FundFeeRule rule=activeRule(family,p.fundId());if(!latest.id().equals(p.navId())||!rule.id().equals(p.feeRuleId())||rule.version()!=p.feeRuleVersion())throw new Stage3Service.ConflictException("NAV or fee rule changed; preview again");WalletRow wallet=lockWallet(family,p.childId());ensurePosition(family,p.childId(),p.fundId(),now);PositionRow pos=lockPosition(family,p.childId(),p.fundId());BigDecimal walletAfter,newShares,newCost,realized=BigDecimal.ZERO,newRealized=pos.realized();if(p.side()==TradeSide.BUY){walletAfter=wallet.money().subtract(p.grossMoney());if(walletAfter.signum()<0)throw new Stage3Service.ConflictException("Money balance is insufficient");newShares=pos.shares().add(p.shares());newCost=pos.cost().add(p.grossMoney());}else{newShares=pos.shares().subtract(p.shares());if(newShares.signum()<0)throw new Stage3Service.ConflictException("Fund shares are insufficient");BigDecimal removed=p.shares().compareTo(pos.shares())==0?pos.cost():pos.cost().divide(pos.shares(),8,RoundingMode.HALF_UP).multiply(p.shares()).setScale(2,RoundingMode.HALF_UP);newCost=pos.cost().subtract(removed);walletAfter=wallet.money().add(p.netMoney());realized=p.netMoney().subtract(removed);newRealized=pos.realized().add(realized);}UUID orderId=UUID.randomUUID(),group=UUID.randomUUID();jdbc.update("INSERT INTO fund_trade_order(id,preview_id,family_id,child_id,fund_id,side,gross_money,fee_amount,net_money,shares,nav,realized_pnl,ledger_group_id,idempotency_key,actor_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",orderId,previewId,family,p.childId(),p.fundId(),p.side().name(),p.grossMoney(),p.feeAmount(),p.netMoney(),p.shares(),p.nav(),realized,group,key,actor,ts(now));BigDecimal delta=p.side()==TradeSide.BUY?p.grossMoney().negate():p.netMoney();insertLedger(family,p.childId(),delta,wallet.money(),walletAfter,orderId,group,key,actor,"Simulated fund "+p.side()+"; fee="+p.feeAmount(),now);jdbc.update("UPDATE wallet SET money_balance=?,version=version+1,updated_at=? WHERE family_id=? AND child_id=?",walletAfter,ts(now),family,p.childId());jdbc.update("UPDATE fund_position SET shares=?,total_cost=?,realized_pnl=?,version=version+1,updated_at=? WHERE child_id=? AND fund_id=?",newShares,newCost,newRealized,ts(now),p.childId(),p.fundId());jdbc.update("UPDATE fund_trade_preview SET status='CONFIRMED',order_id=? WHERE id=?",orderId,previewId);return orderByKey(family,key).orElseThrow();}
 @Override public FundPosition position(UUID family,UUID child,UUID fundId){fund(family,fundId);FundNav nav=latestNav(family,fundId).orElseThrow(()->new Stage3Service.ConflictException("Fund has no NAV"));var row=jdbc.query("SELECT * FROM fund_position WHERE family_id=? AND child_id=? AND fund_id=?",this::positionRow,family,child,fundId).stream().findFirst().orElse(new PositionRow(BigDecimal.ZERO.setScale(8),new BigDecimal("0.00"),new BigDecimal("0.00"),0));BigDecimal avg=row.shares().signum()==0?BigDecimal.ZERO.setScale(8):row.cost().divide(row.shares(),8,RoundingMode.HALF_UP),market=row.shares().multiply(nav.nav()).setScale(2,RoundingMode.DOWN),unrealized=market.subtract(row.cost());return new FundPosition(family,child,fundId,row.shares(),row.cost(),avg,nav.nav(),market,unrealized,row.realized(),row.version());}
 private VirtualFund fund(UUID family,UUID id){return jdbc.query("SELECT * FROM virtual_fund WHERE family_id=? AND id=?",this::fundRow,family,id).stream().findFirst().orElseThrow(FamilyGrowthService.NotFoundException::new);}private VirtualFund lockFund(UUID family,UUID id){return jdbc.query("SELECT * FROM virtual_fund WHERE family_id=? AND id=? FOR UPDATE",this::fundRow,family,id).stream().findFirst().orElseThrow(FamilyGrowthService.NotFoundException::new);}
 private Optional<FundNav> latestNav(UUID family,UUID fund){return jdbc.query("SELECT * FROM fund_nav WHERE family_id=? AND fund_id=? ORDER BY nav_date DESC,created_at DESC LIMIT 1",this::navRow,family,fund).stream().findFirst();}private FundNav navById(UUID id){return jdbc.query("SELECT * FROM fund_nav WHERE id=?",this::navRow,id).stream().findFirst().orElseThrow();}private FundFeeRule activeRule(UUID family,UUID fund){return jdbc.query("SELECT * FROM fund_fee_rule WHERE family_id=? AND fund_id=? AND active=TRUE",this::ruleRow,family,fund).stream().findFirst().orElseThrow(()->new Stage3Service.ConflictException("Fund has no active fee rule"));}
 private WalletRow lockWallet(UUID f,UUID c){return jdbc.query("SELECT money_balance FROM wallet WHERE family_id=? AND child_id=? FOR UPDATE",(rs,row)->new WalletRow(rs.getBigDecimal(1)),f,c).stream().findFirst().orElseThrow(FamilyGrowthService.NotFoundException::new);}private void ensurePosition(UUID f,UUID c,UUID fund,Instant now){if(jdbc.queryForObject("SELECT COUNT(*) FROM fund_position WHERE child_id=? AND fund_id=?",Integer.class,c,fund)==0)jdbc.update("INSERT INTO fund_position(family_id,child_id,fund_id,shares,total_cost,realized_pnl,version,created_at,updated_at) VALUES(?,?,?,0.00000000,0.00,0.00,0,?,?)",f,c,fund,ts(now),ts(now));}private PositionRow lockPosition(UUID f,UUID c,UUID fund){return jdbc.query("SELECT * FROM fund_position WHERE family_id=? AND child_id=? AND fund_id=? FOR UPDATE",this::positionRow,f,c,fund).stream().findFirst().orElseThrow();}
 private void insertLedger(UUID f,UUID c,BigDecimal delta,BigDecimal before,BigDecimal after,UUID business,UUID group,String key,UUID actor,String reason,Instant now){jdbc.update("INSERT INTO ledger_entry(id,family_id,child_id,asset_type,delta,before_balance,after_balance,entry_type,business_type,business_id,group_id,idempotency_key,actor_id,reason,created_at) VALUES(?,?,?,'MONEY',?,?,?,'FUND_TRADE','FUND_TRADE',?,?,?,?,?,?)",UUID.randomUUID(),f,c,delta,before,after,business,group,key,actor,reason,ts(now));}
 private VirtualFund fundRow(ResultSet r,int n)throws SQLException{return new VirtualFund(u(r,"id"),u(r,"family_id"),r.getString("name"),r.getString("risk_label"),r.getBoolean("active"),r.getLong("version"),r.getString("notice"),i(r,"created_at"));}private FundNav navRow(ResultSet r,int n)throws SQLException{return new FundNav(u(r,"id"),u(r,"fund_id"),r.getObject("nav_date",LocalDate.class),r.getBigDecimal("nav"),r.getBigDecimal("change_percent"),i(r,"created_at"));}private FundFeeRule ruleRow(ResultSet r,int n)throws SQLException{return new FundFeeRule(u(r,"id"),u(r,"family_id"),u(r,"fund_id"),r.getLong("rule_version"),r.getBigDecimal("buy_fee_rate"),r.getBigDecimal("sell_fee_rate"),r.getBoolean("active"),i(r,"created_at"));}
 private TradePreview previewRow(ResultSet r,int n)throws SQLException{return new TradePreview(u(r,"id"),u(r,"family_id"),u(r,"child_id"),u(r,"fund_id"),TradeSide.valueOf(r.getString("side")),r.getBigDecimal("input_amount"),r.getBigDecimal("gross_money"),r.getBigDecimal("fee_amount"),r.getBigDecimal("net_money"),r.getBigDecimal("shares"),u(r,"nav_id"),r.getBigDecimal("nav"),u(r,"fee_rule_id"),r.getLong("fee_rule_version"),PreviewStatus.valueOf(r.getString("status")),i(r,"expires_at"),u(r,"order_id"),r.getString("notice"),i(r,"created_at"));}private FundTradeOrder orderRow(ResultSet r,int n)throws SQLException{return new FundTradeOrder(u(r,"id"),u(r,"preview_id"),u(r,"family_id"),u(r,"child_id"),u(r,"fund_id"),TradeSide.valueOf(r.getString("side")),r.getBigDecimal("gross_money"),r.getBigDecimal("fee_amount"),r.getBigDecimal("net_money"),r.getBigDecimal("shares"),r.getBigDecimal("nav"),r.getBigDecimal("realized_pnl"),u(r,"ledger_group_id"),r.getString("idempotency_key"),u(r,"actor_id"),i(r,"created_at"));}private PositionRow positionRow(ResultSet r,int n)throws SQLException{return new PositionRow(r.getBigDecimal("shares"),r.getBigDecimal("total_cost"),r.getBigDecimal("realized_pnl"),r.getLong("version"));}
 private static UUID u(ResultSet r,String c)throws SQLException{return r.getObject(c,UUID.class);}private static Instant i(ResultSet r,String c)throws SQLException{Timestamp t=r.getTimestamp(c);return t==null?null:t.toInstant();}private static Timestamp ts(Instant i){return Timestamp.from(i);}private record WalletRow(BigDecimal money){}private record PositionRow(BigDecimal shares,BigDecimal cost,BigDecimal realized,long version){}
}
